      "tail": ""
    },
    {
      "label": "QUOTE",
      "frame": "རྟེན་འབྲེལ་གྱི་མདོ་འགྲེལ་ལས།",
      "head": "གང་གིས་འཕེན་དང་ཇི་ལྟར་གང་། ། དེ་འགྲུབ་བྱེད་པ་དེ་ལ་ཡང་། ། ཉེས་དམིགས་གང་ཡིན་དེ་དག་རྣམས། ། ཡན་ལག་བཅུ་གཉིས་རྣམས་ཀྱིས་བསྟན། ། གཉིས་ཀྱིས་ཡན་ལག་གཅིག་གིས་དང་། ། རྣམ་པ་བཞི་དང་གཉིས་ཀྱིས་དང་། ། གཅིག་གིས་གཅིག་གི་གཅིག་གི་དང་། ། དོན་བདུན་དག་ཏུ་རབ་ཏུ་བསྟན། ། བདེན་པ་ཇི་བཞིན་མི་ཤེས་ཕྱིར། ། ལས་ཀྱིས་སེམས་ལ་བསྒོས་པའི་ཕྱིར། ། ཡན་ལག་བཞི་ནི་རིམ་གྱིས་འཕེན། ། དེ་ཡི་ས་བོན་ཡང་བརྟས་ཕྱིར། ། འཕངས་པ་བཞིན་དུ་སྐྱེས་པ་ཡི། ། ཚོར་བས་བསྐྱེད་པའི་སྲེད་པ་ལ། ། ལེན་པ་འབྱུང་བས་དེ་ཡི་ལས། ། དགོས་པ་མངོན་དུ་འགྱུར་བ་ཡིན། ། གྲུབ་པ་སྐྱེ་བཞིན་དེ་ལ་ཡང་། ། རྒ་སོགས་ཉེས་དམིགས་གང་གི་ཕྱིར། ། བདེན་པ་མཐོང་ལ་འཕེན་བྱེད་མེད། ། སྲེད་དང་བྲལ་ལ་འབྱུང་བ་མེད།",
      "tail": "སྲེད་དང་བྲལ་ལ་འབྱུང་བ་མེད།"
    },
