      "tail": "རྒྱུ་ཅན་འདི་ནི་འཁོར་བར་འགྱུར།"
    },
    {
      "label": "QUOTE",
      "frame": "རྟེན་འབྲེལ་སྙིང་པོ་ལས།",
      "head": "གསུམ་པོ་དག་ལས་གཉིས་འབྱུང་ཞིང་། ། གཉིས་ལས་བདུན་འབྱུང་བདུན་ལས་ཀྱང་། ། གསུམ་འབྱུང་སྲིད་པའི་འཁོར་ལོ་སྟེ། ། དེ་ཉིད་ཡང་དང་ཡང་དུ་འཁོར།",
